func (c activityCatalog) CreateActivity(ctx context.Context, input devicescan.NewActivity) (devicescan.Activity, error) {
	created, err := c.activities.CreateCatalogGroup(ctx, timetable.GroupInput{Name: input.Name, MaxParticipants: input.MaxParticipants, IsOpen: input.IsOpen, CategoryID: input.CategoryID, PlannedRoomID: input.PlannedRoomID, IsSystem: input.IsSystem})
	if err != nil {
		return devicescan.Activity{}, err
	}
	return *activityFromGroup(&created), nil
}

func (c activityCatalog) CreateCategory(ctx context.Context, input devicescan.NewCategory) (devicescan.Category, error) {
	created, err := c.activities.CreateCatalogCategory(ctx, timetable.CreateCategory{Name: input.Name, Description: input.Description, Color: input.Color, IsSystem: input.IsSystem})
	if err != nil {
		return devicescan.Category{}, err
	}
	return devicescan.Category{ID: created.ID, Name: created.Name}, nil
}

func (c activityCatalog) Find(ctx context.Context, id int64) (*devicescan.Activity, error) {
	group, err := c.activities.FindCatalogGroup(ctx, id)
	if err != nil {
		return nil, err
	}
	return activityFromGroup(group), nil
}

func (c activityCatalog) ListByName(ctx context.Context, name string) ([]devicescan.Activity, error) {
	groups, err := c.activities.ListCatalogGroups(ctx, name)
	if err != nil {
		return nil, err
	}
	result := make([]devicescan.Activity, 0, len(groups))
	for _, group := range groups {
		if activity := activityFromGroup(&group); activity != nil {
			result = append(result, *activity)
		}
	}
	return result, nil
}

func (c activityCatalog) ListCategories(ctx context.Context) ([]devicescan.Category, error) {
	categories, err := c.activities.ListCatalogCategories(ctx)
	if err != nil {
		return nil, err
	}
	result := make([]devicescan.Category, 0, len(categories))
	for _, category := range categories {
		result = append(result, devicescan.Category{ID: category.ID, Name: category.Name})
	}
	return result, nil
}

func (m mirrorTimetable) ActivityTitle(ctx context.Context, activityID int64) (string, error) {
	if m.activities == nil {
		return "", nil
	}
	group, err := m.activities.FindCatalogGroup(ctx, activityID)
	if group == nil {
		return "", err
	}
	return group.Name, err
}

func (m mirrorTimetable) HasInstance(ctx context.Context, sessionID int64) (bool, error) {
	instance, err := m.records.FindSessionInstance(ctx, sessionID)
	return instance != nil, err
}

func (req *SessionActivityRequest) Bind(_ *http.Request) error {
	if err := validation.ValidateStruct(req, validation.Field(&req.ActivityType, validation.Required, validation.In("rfid_scan", "button_press", "ui_interaction"))); err != nil {
		return err
	}
	if req.Timestamp.IsZero() {
		req.Timestamp = time.Now()
	}
	return nil
}

