func (p pickupPlan) Effective(ctx context.Context, studentID int64, day calendar.Date) (*ports.Pickup, error) {
	effective, err := p.pickups.GetEffectivePickupTimeForDate(ctx, studentID, day)
	if err != nil {
		return nil, err
	}
	if effective == nil {
		return nil, nil
	}
	pickup := &ports.Pickup{Time: effective.PickupTime, Notes: effective.Notes}
	for _, note := range effective.DayNotes {
		pickup.DayNotes = append(pickup.DayNotes, note.Content)
	}
	return pickup, nil
}

func (s sessions) Current(ctx context.Context, deviceID int64) (*devicescan.Session, error) {
	group, err := s.active.GetDeviceCurrentSession(ctx, deviceID)
	if err != nil {
		if errors.Is(err, studentpresence.ErrNoActiveSession) {
			return nil, nil
		}
		return nil, err
	}
	if group == nil {
		return nil, nil
	}
	session := sessionFromGroup(group)
	return &session, nil
}

func (s sessions) End(ctx context.Context, sessionID int64) error {
	err := s.active.EndActiveGroupSession(ctx, sessionID)
	if err != nil && !errors.Is(err, studentpresence.ErrGroupAlreadyEnded) {
		return err
	}
	return nil
}

func (s sessions) EnsureRoomSession(ctx context.Context, input devicescan.NewSession) (devicescan.Session, error) {
	group, err := s.active.EnsureOpenRoomSession(ctx, input.RoomID, input.ActivityID)
	if err != nil {
		return devicescan.Session{}, err
	}
	return sessionFromGroup(group), nil
}

func (s sessions) FindDeviceSessionInRoom(ctx context.Context, roomID, deviceID int64) (*devicescan.Session, error) {
	group, err := s.active.FindDeviceActiveGroupInRoom(ctx, roomID, deviceID)
	if err != nil {
		return nil, err
	}
	if group == nil {
		return nil, nil
	}
	session := sessionFromGroup(group)
	return &session, nil
}

func (s sessions) ListOpenInRoom(ctx context.Context, roomID int64) ([]devicescan.Session, error) {
	groups, err := s.presence.QueryLiveGroups(ctx, studentpresence.LiveGroupFilter{RoomID: &roomID, OpenOnly: true})
	if err != nil {
		return nil, &studentpresence.OperationError{Op: "FindActiveGroupsByRoomID", Err: fmt.Errorf("find by room: %w", err)}
	}
	result := make([]devicescan.Session, 0, len(groups))
	for _, group := range groups {
		result = append(result, devicescan.Session{ID: group.ID, RoomID: group.RoomID, StartTime: group.StartTime, EndTime: group.EndTime, DeviceID: group.DeviceID, TemplateID: group.ActivityGroupID})
	}
	return result, nil
}

func (s sessions) ReplaceSupervisors(ctx context.Context, sessionID int64, staffIDs []int64) error {
	_, err := s.active.UpdateActiveGroupSupervisors(ctx, sessionID, staffIDs)
	return err
}

func (q supervisionQuery) ActiveSupervisions(ctx context.Context, sessionID int64) ([]devicescan.Supervision, error) {
	today := calendar.TodayDate()
	day := today.String()
	rows, err := q.source.QueryGroupSupervisions(ctx, studentpresence.GroupSupervisionFilter{GroupIDs: []int64{sessionID}, ActiveOn: &day})
	if err != nil {
		return nil, &studentpresence.OperationError{Op: "FindSupervisorsByActiveGroupID", Err: studentpresence.ErrDatabaseOperation}
	}
	result := make([]devicescan.Supervision, 0, len(rows))
	for _, row := range rows {
		result = append(result, devicescan.Supervision{StaffID: row.StaffID, Role: row.Role, Ended: supervisionEnded(row.EndDate, today.String())})
	}
	return result, nil
}
